import { describe, test, expect } from 'vitest';
import { breakpoints } from 'app/theme/foundation';
import { ZimmDrawer } from './zimmDrawer.css';

const MD_UP = `@media (min-width: ${breakpoints.md})`;

describe('ZimmDrawer recipe', () => {
  // SFCC-736 AC 9 — PO-approved 2026-08-21: the `mobile` size must leave a 58px backdrop strip
  // below the panel so users can tap to dismiss. This value is a provisional raw constant
  // (3.625rem = 58px) pending a foundation token — if the token lands, update it here too.
  test('mobile variant applies the 58px backdrop strip', () => {
    const mobileHeight = ZimmDrawer.variants.mobile.content.height;
    expect(mobileHeight).toBe('calc(100% - 3.625rem)');
  });

  // The baseStyle must be full-height so utility drawers (e.g. wishlist auth, SFCC-926) that
  // use a desktop size (large/small) on narrow viewports inherit full height without opting in.
  test('baseStyle content is full-height', () => {
    expect(ZimmDrawer.baseStyle.content.height).toBe('100%');
  });

  // SFCC-11 (Cart): the real cart panel is a FIXED 1186px at both 1440 and 1920 (Figma node
  // 9323:65888/65895, file QQ427wHWEUjsjP7H8v48Rs) — not 82% of viewport, which the "X-Large"
  // named-size library annotation says but which overshoots by 388px at 1920. maxWidth is a
  // literal 100% cap, not the width constant, so a viewport narrower than 1186px but still
  // above `md` doesn't overflow.
  test('xLarge variant applies the measured 1186px cart panel width above md', () => {
    const xLargeAtMd = ZimmDrawer.variants.xLarge.content[MD_UP];
    expect(xLargeAtMd.width).toBe('74.125rem');
    expect(xLargeAtMd.maxWidth).toBe('100%');
  });

  // The xLarge fix must not perturb any other size's resolved output.
  test('other size variants are unchanged by the xLarge width fix', () => {
    expect(ZimmDrawer.variants.large.content[MD_UP]).toEqual({
      width: '50%',
      maxWidth: '50%',
      height: '100%',
    });
    expect(ZimmDrawer.variants.tablet.content[MD_UP]).toEqual({
      width: '80%',
      maxWidth: '80%',
      height: '100%',
    });
    expect(ZimmDrawer.variants.small.content[MD_UP]).toEqual({
      width: '25%',
      maxWidth: '25%',
      height: '100%',
    });
    expect(ZimmDrawer.variants.mobile.content.height).toBe('calc(100% - 3.625rem)');
  });
});

// Shared between the drawer/tabs recipe files that must stay in the same 44px band —
// zimmDrawer.css.ts's `closeButton` and zimmTabs.css.ts's `menu` — so the value can't drift the
// way a copy-pasted literal would. Not a general-purpose theme module — scope stays this one
// drawer-header row; see .claude/rules/overrideStyling.md's co-location guidance for the pattern
// this follows (footerShared.ts is the reference example).

// Figma's drawer-header-options row height (SFCC-898) — measured at 44px on every captured
// frame (desktop, tablet, mobile). ZimmDrawer's closeButton is a separate, independently
// positioned element from ZimmTabs' own tab row (not a child of the same flex row the way
// Figma has them), so matching this same explicit height on both is what keeps their vertical
// centers aligned by construction rather than by coincidence of the tab text's own line-height.
export const DRAWER_HEADER_ROW_HEIGHT = '2.75rem'; // 44px
